import{af as t,z as a,J as r,ab as i}from"./chunks/framework.C1QHhBQn.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/troubleshooting.md","filePath":"faq/troubleshooting.md"}'),o={name:"faq/troubleshooting.md"};function n(s,e,l,h,c,d){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#why-are-location-updates-not-instant">Why are location updates not instant? ​</a></li><li><a href="#why-are-two-lights-red-and-four-orange">Why are two lights red and four orange? ​</a></li><li><a href="#why-is-my-tracker-not-transmitting">Why is my tracker not transmitting? ​</a></li><li><a href="#restarting-a-tracker">Restarting a tracker ​</a></li><li><a href="#why-is-my-tracker-giving-inaccurate-locations">Why is my tracker giving inaccurate locations? ​</a></li><li><a href="#why-is-my-battery-not-lasting-as-long-as-advertised">Why is my battery not lasting as long as advertised? ​</a></li></ul></nav><h2 id="why-are-location-updates-not-instant" tabindex="-1">Why are location updates not instant? <a class="header-anchor" href="#why-are-location-updates-not-instant" aria-label="Permalink to &quot;Why are location updates not instant?&quot;">​</a></h2><p>In many cases, location can not be retrieved instantly, it takes time to get a <a href="/docs/pr/40/terminology/positioning/gnss">GPS fix</a> and if that fails, the <a href="/docs/pr/40/terminology/positioning/">other location technologies</a> come into action.</p><p>After a device has determined its location, it has to connect to the internet via the mobile networks in order to send the location information.</p><p>Once the information has been received by our servers, during normal operation it should be visible to you within a few seconds.</p><h2 id="why-are-two-lights-red-and-four-orange" tabindex="-1">Why are two lights red and four orange? <a class="header-anchor" href="#why-are-two-lights-red-and-four-orange" aria-label="Permalink to &quot;Why are two lights red and four orange?&quot;">​</a></h2><p>On a Pro PR2 (device ID prefix 20), this can be part of a normal restart. Other Pro versions have different LED hardware. It is not by itself a fault code or a full-battery reading. Give the tracker time to start, then check its latest update in the app or portal before resetting it again.</p><p>See the <a href="/docs/pr/40/guides/tracker-leds#two-red-lights-and-four-orange-lights-after-a-restart">illustrated LED guide</a> for the pattern, normal battery/status meanings and when to contact support.</p><h2 id="why-is-my-tracker-not-transmitting" tabindex="-1">Why is my tracker not transmitting? <a class="header-anchor" href="#why-is-my-tracker-not-transmitting" aria-label="Permalink to &quot;Why is my tracker not transmitting?&quot;">​</a></h2><p>Always give your tracker a couple of minutes to send a location update.</p><p>If it still hasn&#39;t sent a location update, make sure:</p><ul><li>Your device has an active data plan</li><li>Your device is charged</li><li>The tracker is in an area with good mobile coverage</li></ul><p>If you have checked the above and your tracker is still not transmitting, try the following:</p><ul><li>Request a location update using the button action documented for your device and application</li><li>If needed, follow the <a href="#restarting-a-tracker">restart guidance</a> for your model and firmware</li><li>Place the tracker outside for 5 minutes after completing all the above</li></ul><p>If the tracker is still not transmitting, please contact us.</p><h2 id="restarting-a-tracker" tabindex="-1">Restarting a tracker <a class="header-anchor" href="#restarting-a-tracker" aria-label="Permalink to &quot;Restarting a tracker&quot;">​</a></h2><p>Do not repeatedly reset a tracker just because a light is red. First check the <a href="/docs/pr/40/guides/leds">LED guide for your model</a> and the latest successful communication.</p><p>On standard current firmware for ProN/PR2, Zero/ZE2, Enviro/EN2, Pro3, VT3 and RH2, a long press reaches the restart action after about 10 seconds. <strong>Release when the restart begins.</strong> Button behaviour, the button to use and any sound can vary by model, application and firmware version. There is no universal beep or LED sequence.</p><p>Depending on firmware and reset history, a long-press restart can clear settings or enter recovery mode. Do not assume this action always preserves settings. If the installed firmware or button behaviour is uncertain, check with <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">support</a> before proceeding. Use the procedure supplied for other models.</p><h2 id="why-is-my-tracker-giving-inaccurate-locations" tabindex="-1">Why is my tracker giving inaccurate locations? <a class="header-anchor" href="#why-is-my-tracker-giving-inaccurate-locations" aria-label="Permalink to &quot;Why is my tracker giving inaccurate locations?&quot;">​</a></h2><p>Location accuracy depends on several variables.</p><p>There are a few good practices that help improve the location accuracy of your tracker.</p><ul><li>Try to place your tracker with the logo facing up (this is where the GPS antenna is located)</li><li>Avoid surrounding your tracker with metals as they block GPS and GSM signals</li><li>To allow for more GPS locations to be gathered, try to place your tracker somewhere with a good line of sight with the sky</li><li>Increase the GPS timeout</li><li>Make sure you have the correct settings. If you are unsure, please get in touch and we will assist!</li></ul><h2 id="why-is-my-battery-not-lasting-as-long-as-advertised" tabindex="-1">Why is my battery not lasting as long as advertised? <a class="header-anchor" href="#why-is-my-battery-not-lasting-as-long-as-advertised" aria-label="Permalink to &quot;Why is my battery not lasting as long as advertised?&quot;">​</a></h2><p>The advertised values are general guidelines.</p><p>In reality, there are many variables that affect battery life, such as:</p><ul><li>Where the tracker is mounted: with a clear line of sight with the sky, the tracker will use less power per location update</li><li>Is the tracker indoors? If the tracker is indoor, more power will be used as the tracker will try to look for a GPS fix before attempting to locate itself via WPS or GSM. Find out more about this under the How the location technologies work section</li><li>Make sure you have Wi-Fi and GPS Safe Zones set up where applicable</li><li>Motion sensitivity: maybe your tracker is sending more location updates than it should because the motion sensitivity is too high. This usually occurs when the tracker is stationary but still sending location updates. Reduce the motion sensitivity via your flexible configurations page.</li></ul><p>You can always <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact our support team</a> for help with this.</p>',29)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
